public 
enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The token was refused: the device was revoked, or the registration token is wrong.
     */
    case Unauthorized
    /**
     * Too many failed attempts from this address; try again after the given seconds.
     */
    case RateLimited(retryAfterSecs: UInt64
    )
    case NotFound
    /**
     * The server could not be reached.
     */
    case Network(message: String
    )
    case Server(status: UInt16
    )
    case Other(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CoreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Unauthorized
        case 2: return .RateLimited(
            retryAfterSecs: try FfiConverterUInt64.read(from: &buf)
            )
        case 3: return .NotFound
        case 4: return .Network(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Server(
            status: try FfiConverterUInt16.read(from: &buf)
            )
        case 6: return .Other(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .Unauthorized:
            writeInt(&buf, Int32(1))
        
        
        case let .RateLimited(retryAfterSecs):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(retryAfterSecs, into: &buf)
            
        
        case .NotFound:
            writeInt(&buf, Int32(3))
        
        
        case let .Network(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Server(status):
            writeInt(&buf, Int32(5))
            FfiConverterUInt16.write(status, into: &buf)
            
        
        case let .Other(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreError_lift(_ buf: RustBuffer) throws -> CoreError {
    return try FfiConverterTypeCoreError.lift(buf)
}

